254	func containsHit(hits []TxHit, want TxHit) bool {
255		for _, hit := range hits {
256			if hit == want {
257				return true
258			}
259		}
260		return false
261	}
262	
263	func requireOrdered(t *testing.T, hits []TxHit) {
264		t.Helper()
265		for i := 1; i < len(hits); i++ {
266			prev, cur := hits[i-1], hits[i]
267			if cur.Height < prev.Height || (cur.Height == prev.Height && cur.Position <= prev.Position) {
268				t.Fatalf("hits not ordered at %d: %+v after %+v", i, cur, prev)
269			}
270		}
271	}
