515	// Ordering 1: the first page is holding the lock on the complete OLD chain
516	// when the shortening reorg starts. It must finish on the old chain; once the
517	// reorg completes, its cursor is dead.
518	func TestQueryTxsFirstPageInFlightObservesCompleteOldChain(t *testing.T) {
519		index := buildQueryOldChain(t)
520		h := installQueryReorgHooks(t, true, false, 4)
521		oldChain, newChain := queryOldChainBlocks(), queryNewChainBlocks()
522	
523		result := make(chan TxPage, 1)
524		errCh := make(chan error, 1)
525		go func() {
526			page, err := index.QueryTxs(TxQuery{PageSize: 3})
527			if err != nil {
528				errCh <- err
529				return
530			}
531			result <- page
532		}()
533	
534		<-h.firstParked // query holds index.mu and has pinned tip 5
535		reorgDone := make(chan struct{})
536		go func() {
537			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
538				errCh <- err
539			}
540			close(reorgDone)
541		}()
542	
543		close(h.releaseFirst) // query scans and finishes first; reorg cannot apply yet
544		var got TxPage
545		select {
546		case got = <-result:
547		case err := <-errCh:
548			t.Fatalf("concurrent call failed: %v", err)
549		}
550		want := referenceTxPage(oldChain, 3, 0)
551		if err := classifyTxPage(got, want, referenceTxPage(newChain, 3, 0),
552			referenceTxHits(oldChain), referenceTxHits(newChain)); err != nil {
553			t.Fatalf("in-flight first page did not return one complete chain:\n%v", err)
554		}
555		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
556			t.Fatalf("query holding the lock across reorg start must see old chain:\n%+v", got)
557		}
558		if !reflect.DeepEqual(got.Hits, literalOldFirstPage().Hits) {
559			t.Fatalf("old first page hits=%v, want literal old records", got.Hits)
560		}
561		if got.NextCursor == "" {
562			t.Fatal("old first page over 10 matches must carry a cursor")
563		}
564	
565		close(h.releaseReorg) // now let the parked reorg commit and return
566		<-reorgDone
567		if index.Tip != 4 {
568			t.Fatalf("tip after reorg=%d, want 4", index.Tip)
569		}
570	
571		// The cursor pins the OLD branch (tip 5, offset 3, old fingerprint); on
572		// the new chain it must fail rather than resume on mixed data.
573		oldFingerprint := buildQueryOldChain(t)
574		payload := decodePayload(t, index, got.NextCursor)
575		if payload.To != 5 || payload.Off != 3 {
576			t.Fatalf("cursor pins to=%d off=%d, want 5/3", payload.To, payload.Off)
577		}
578		if payload.FP != fmt.Sprintf("%x", oldFingerprint.fingerprintLocked(1, 5)) {
579			t.Fatal("cursor fingerprint does not match the complete old chain")
580		}
581		page, err := index.QueryTxs(TxQuery{PageSize: 3, Cursor: got.NextCursor})
582		if !errors.Is(err, ErrQueryChanged) {
583			t.Fatalf("old cursor across reorg: err=%v page=%+v, want ErrQueryChanged", err, page)
584		}
585		if !reflect.DeepEqual(page, TxPage{}) {
586			t.Fatalf("changed continuation must return a zeroed page, got %+v", page)
587		}
588	}
