590	// Ordering 2: the shortening reorg has fully committed (new chain installed,
591	// Reorg still holding the lock) when the first page starts. It must wait and
592	// then answer on the complete NEW chain, and its cursor must paginate the new
593	// branch to the end.
594	func TestQueryTxsFirstPageDuringCommittedReorgObservesCompleteNewChain(t *testing.T) {
595		index := buildQueryOldChain(t)
596		h := installQueryReorgHooks(t, true, false, 4)
597		oldChain, newChain := queryOldChainBlocks(), queryNewChainBlocks()
598	
599		reorgErr := make(chan error, 1)
600		go func() {
601			_, err := index.Reorg(queryNewShortBranch())
602			reorgErr <- err
603		}()
604		<-h.reorgParked // new branch applied (tip 4), Reorg still holds the lock
605	
606		result := make(chan TxPage, 1)
607		go func() {
608			page, err := index.QueryTxs(TxQuery{PageSize: 3})
609			if err != nil {
610				t.Errorf("query during reorg failed: %v", err)
611				return
612			}
613			result <- page
614		}()
615	
616		close(h.releaseReorg) // reorg returns; the first lock the query can get sees the new chain
617		if err := <-reorgErr; err != nil {
618			t.Fatalf("reorg failed: %v", err)
619		}
620		close(h.releaseFirst) // the parked first page can now scan and finish
621	
622		got := <-result
623		want := referenceTxPage(newChain, 3, 0)
624		if err := classifyTxPage(got, referenceTxPage(oldChain, 3, 0), want,
625			referenceTxHits(oldChain), referenceTxHits(newChain)); err != nil {
626			t.Fatalf("first page across reorg commit did not return one complete chain:\n%v", err)
627		}
628		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
629			t.Fatalf("query after reorg commit must see the complete new chain:\n%+v", got)
630		}
631		if !reflect.DeepEqual(got.Hits, literalNewFirstPage().Hits) {
632			t.Fatalf("new first page hits=%v, want literal new records", got.Hits)
633		}
634		if got.NextCursor == "" {
635			t.Fatal("new first page over 8 matches must carry a cursor")
636		}
637	
638		// The cursor pins the NEW branch; following it must drain exactly the new
639		// records with statistics pinned to the first page — no old-suffix leak.
640		newFingerprint := New()
641		for _, b := range newChain {
642			if err := newFingerprint.Append(b); err != nil {
643				t.Fatal(err)
644			}
645		}
646		payload := decodePayload(t, index, got.NextCursor)
647		if payload.To != 4 || payload.Off != 3 {
648			t.Fatalf("cursor pins to=%d off=%d, want 4/3", payload.To, payload.Off)
649		}
650		if payload.FP != fmt.Sprintf("%x", newFingerprint.fingerprintLocked(1, 4)) {
651			t.Fatal("cursor fingerprint does not match the complete new chain")
652		}
653	
654		query := TxQuery{PageSize: 3, Cursor: got.NextCursor}
655		var all = append([]TxHit{}, got.Hits...)
656		for pageNo := 1; ; pageNo++ {
657			page, err := index.QueryTxs(query)
658			if err != nil {
659				t.Fatalf("new-chain pagination broke at page %d: %v", pageNo, err)
660			}
661			if page.TotalMatches != 8 || page.MatchedBlocks != 4 || page.ToHeight != 4 {
662				t.Fatalf("page %d statistics drifted from the pinned first page: %+v", pageNo, page)
663			}
664			all = append(all, page.Hits...)
665			if page.NextCursor == "" {
666				break
667			}
668			query.Cursor = page.NextCursor
669		}
670		if !reflect.DeepEqual(all, referenceTxHits(newChain)) {
671			t.Fatalf("new-chain pagination=%v, want %v", all, referenceTxHits(newChain))
672		}
673	}
674	
675	// viewOf strips the opaque cursor for whole-page DeepEqual comparisons.
676	func viewOf(page TxPage) TxPage {
677		page.NextCursor = ""
678		return page
679	}
680	
681	// After the first page pinned its range, every continuation outcome is
682	// deterministic: a block inside the pinned range changed or the chain shrank
683	// below the pinned upper bound -> ErrQueryChanged with a fully zeroed result.
684	func TestQueryTxsContinuationAfterReorgIsChangedAndZeroed(t *testing.T) {
685		t.Run("suffix replaced under a pinned tip", func(t *testing.T) {
686			index := buildQueryOldChain(t)
687			first, err := index.QueryTxs(TxQuery{PageSize: 3})
688			if err != nil {
689				t.Fatal(err)
690			}
691			if first.NextCursor == "" || first.ToHeight != 5 || first.TotalMatches != 10 {
692				t.Fatalf("unexpected first page: %+v", first)
693			}
694			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
695				t.Fatal(err)
696			}
697			page, err := index.QueryTxs(TxQuery{PageSize: 3, Cursor: first.NextCursor})
698			requireChangedZeroed(t, page, err)
699		})
700	
701		t.Run("chain shortened below an explicit to", func(t *testing.T) {
702			index := buildQueryOldChain(t)
703			first, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3})
704			if err != nil {
705				t.Fatal(err)
706			}
707			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
708				t.Fatal(err) // tip becomes 4, below the pinned to 5
709			}
710			page, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3, Cursor: first.NextCursor})
711			requireChangedZeroed(t, page, err)
712		})
713	
714		t.Run("block replaced inside the pinned range with the tip intact", func(t *testing.T) {
715			index := buildQueryOldChain(t)
716			first, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3})
717			if err != nil {
718				t.Fatal(err)
719			}
720			// Same length as the old suffix, different content starting at h3:
721			// the tip stays 5 but the pinned fingerprint must not match.
722			sameLength := []Block{
723				{Height: 3, Hash: "k3", Parent: "h2", Txs: []string{"k"}},
724				{Height: 4, Hash: "k4", Parent: "k3", Txs: []string{"k"}},
725				{Height: 5, Hash: "k5", Parent: "k4", Txs: []string{"k"}},
726			}
727			if _, err := index.Reorg(sameLength); err != nil {
728				t.Fatal(err)
729			}
730			if index.Tip != 5 {
731				t.Fatalf("setup: tip must stay 5, got %d", index.Tip)
732			}
733			page, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3, Cursor: first.NextCursor})
734			requireChangedZeroed(t, page, err)
735	
736			// The index stays usable: a fresh first page describes the new chain.
737			fresh, err := index.QueryTxs(TxQuery{PageSize: 100})
738			if err != nil {
739				t.Fatal(err)
740			}
741			liveChain := append([]Block{}, queryRetainedBlocks()...)
742			liveChain = append(liveChain, sameLength...)
743			want := referenceTxPage(liveChain, 100, 0)
744			if !reflect.DeepEqual(viewOf(fresh), viewOf(want)) {
745				t.Fatalf("fresh page=%+v, want %+v", fresh, want)
746			}
747		})
748	}
749	
750	func requireChangedZeroed(t *testing.T, page TxPage, err error) {
751		t.Helper()
752		if !errors.Is(err, ErrQueryChanged) {
753			t.Fatalf("err=%v, want ErrQueryChanged (page=%+v)", err, page)
754		}
755		if errors.Is(err, ErrInvalidArgument) {
756			t.Fatalf("a committed reorg must not be reported as an argument error: %v", err)
757		}
758		if !reflect.DeepEqual(page, TxPage{}) {
759			t.Fatalf("changed continuation must return no records, cursor, or statistics; got %+v", page)
760		}
761	}
762	
763	// A continuation that has already verified the pinned range while the OLD
764	// chain is complete may return the old next page even if a reorg is waiting
765	// for the lock. Its statistics and pinned height must match the first page;
766	// after the reorg commits, every old cursor is dead.
767	func TestQueryTxsContinuationInFlightObservesCompleteOldChainThenDies(t *testing.T) {
768		index := buildQueryOldChain(t)
769		oldChain := queryOldChainBlocks()
770	
771		first, err := index.QueryTxs(TxQuery{PageSize: 2})
772		if err != nil {
773			t.Fatal(err)
774		}
775		if !reflect.DeepEqual(first.Hits, referenceTxPage(oldChain, 2, 0).Hits) {
776			t.Fatalf("first page=%+v", first)
777		}
778		cursorOne := first.NextCursor
779	
780		h := installQueryReorgHooks(t, false, true, 4)
781	
782		result := make(chan TxPage, 1)
783		errCh := make(chan error, 1)
784		go func() {
785			page, err := index.QueryTxs(TxQuery{PageSize: 2, Cursor: cursorOne})
786			if err != nil {
787				errCh <- err
788				return
789			}
790			result <- page
791		}()
792	
793		<-h.contParked // continuation passed every pinned-range check on the old chain
794		reorgDone := make(chan struct{})
795		go func() {
796			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
797				errCh <- err
798			}
799			close(reorgDone)
800		}()
801	
802		close(h.releaseCont) // continuation finishes on the complete old chain first
803		var second TxPage
804		select {
805		case second = <-result:
806		case err := <-errCh:
807			t.Fatalf("concurrent call failed: %v", err)
808		}
809		wantSecond := referenceTxPage(oldChain, 2, 2) // y at h2, then a at h3
810		if !reflect.DeepEqual(viewOf(second), viewOf(wantSecond)) {
811			t.Fatalf("old next page=%+v, want complete old-chain page %+v", second, wantSecond)
812		}
813		// Whole-range statistics and the pinned upper height are exactly those of
814		// the first page, even though the reorg is committed a moment later.
815		if second.TotalMatches != first.TotalMatches ||
816			second.MatchedBlocks != first.MatchedBlocks ||
817			second.ToHeight != first.ToHeight {
818			t.Fatalf("continuation stats=%d/%d/%d differ from first page %d/%d/%d",
819				second.TotalMatches, second.MatchedBlocks, second.ToHeight,
820				first.TotalMatches, first.MatchedBlocks, first.ToHeight)
821		}
822		if second.NextCursor == "" {
823			t.Fatal("six old hits remain, expected another cursor")
824		}
825	
826		close(h.releaseReorg)
827		<-reorgDone
828	
829		// Every cursor minted against the old chain is now dead, including the
830		// first one, and neither leaks records: both return fully zeroed pages.
831		for name, cursor := range map[string]string{"page one": cursorOne, "page two": second.NextCursor} {
832			page, err := index.QueryTxs(TxQuery{PageSize: 2, Cursor: cursor})
833			if !errors.Is(err, ErrQueryChanged) || !reflect.DeepEqual(page, TxPage{}) {
834				t.Fatalf("%s cursor after reorg: page=%+v err=%v, want zeroed ErrQueryChanged", name, page, err)
835			}
836		}
837		// A fresh first page starts over on the complete new chain.
838		fresh, err := index.QueryTxs(TxQuery{PageSize: 3})
839		if err != nil {
840			t.Fatal(err)
841		}
842		if !reflect.DeepEqual(viewOf(fresh), viewOf(referenceTxPage(queryNewChainBlocks(), 3, 0))) {
843			t.Fatalf("fresh page after reorg=%+v", fresh)
844		}
845	}
846	
847	// Fixed-range boundary: when a reorg only replaces the suffix ABOVE the pinned
848	// range and the new chain still covers the pinned upper bound, an outstanding
849	// cursor keeps working. Remaining records are neither lost nor duplicated and
850	// no out-of-range transaction enters the result.
851	func TestQueryTxsCursorSurvivesOutOfRangeShorteningReorg(t *testing.T) {
852		// Heights 1..5 come from the shared fixture (so the pinned prefix has its
853		// literal records); height 6 extends the old tip with a suffix-only block.
854		index := buildQueryOldChain(t)
855		if err := index.Append(Block{Height: 6, Hash: "h6", Parent: "h5", Txs: []string{"z"}}); err != nil {
856			t.Fatalf("setup append at 6: %v", err)
857		}
858		pinnedChain := queryOldChainBlocks()[:4] // heights 1..4: x,x,y,a,c,d,d
859		first, err := index.QueryTxs(TxQuery{From: 1, To: 4, PageSize: 2})
860		if err != nil {
861			t.Fatal(err)
862		}
863		wantFirst := referenceTxPage(pinnedChain, 2, 0)
864		if !reflect.DeepEqual(viewOf(first), viewOf(wantFirst)) || first.NextCursor == "" {
865			t.Fatalf("unexpected first page: %+v", first)
866		}
867	
868		// Replace heights 5..6 with a shorter suffix whose tip (5) still covers
869		// the pinned upper bound 4. Nothing inside [1,4] changes.
870		dropped, err := index.Reorg([]Block{
871			{Height: 5, Hash: "k5", Parent: "h4", Txs: []string{"nb1", "nb2"}},
872		})
873		if err != nil {
874			t.Fatalf("out-of-range reorg refused: %v", err)
875		}
876		if !reflect.DeepEqual(dropped, []int64{5, 6}) || index.Tip != 5 {
877			t.Fatalf("unexpected reorg outcome: dropped=%v tip=%d", dropped, index.Tip)
878		}
879	
880		query := TxQuery{From: 1, To: 4, PageSize: 2, Cursor: first.NextCursor}
881		all := append([]TxHit{}, first.Hits...)
882		pages := 1
883		for {
884			page, err := index.QueryTxs(query)
885			if err != nil {
886				t.Fatalf("cursor must survive a reorg confined above the pinned range: %v", err)
887			}
888			if page.TotalMatches != 7 || page.MatchedBlocks != 4 || page.ToHeight != 4 {
889				t.Fatalf("pinned statistics drifted: %+v", page)
890			}
891			for _, hit := range page.Hits {
892				if hit.Height > 4 {
893					t.Fatalf("out-of-range height entered the result: %+v", hit)
894				}
895				if hit.BlockHash == "h5" || hit.BlockHash == "h6" || hit.BlockHash == "k5" {
896					t.Fatalf("out-of-range block %q entered the result", hit.BlockHash)
897				}
898				if hit.TxID == "e" || hit.TxID == "f" || hit.TxID == "g" || hit.TxID == "z" ||
899					hit.TxID == "nb1" || hit.TxID == "nb2" {
900					t.Fatalf("out-of-range transaction %q entered the result", hit.TxID)
901				}
902			}
903			all = append(all, page.Hits...)
904			pages++
905			if page.NextCursor == "" {
906				break
907			}
908			query.Cursor = page.NextCursor
909		}
910		if !reflect.DeepEqual(all, referenceTxHits(pinnedChain)) {
911			t.Fatalf("pinned records lost or duplicated:\n got=%v\nwant=%v", all, referenceTxHits(pinnedChain))
912		}
913		if pages != 4 {
914			t.Fatalf("pages=%d, want 4 (2/2/2/1 over seven hits)", pages)
915		}
916	}
917	
918	// Sustained overlap with no hooks: reorgers alternate between the tip-5 old
919	// suffix and the shortened tip-4 branch while readers paginate continuously.
920	// Timing-independent — every first page must classify as one complete chain,
921	// every continuation must either continue that exact branch or fail with a
922	// zeroed ErrQueryChanged, and readers pinned to the retained prefix never
923	// fail at all. A torn answer fails under any scheduling.
924	func TestQueryTxsRepeatedShorteningReorgsStayConsistent(t *testing.T) {
925		index := buildQueryOldChain(t)
926		oldHits := referenceTxHits(queryOldChainBlocks())
927		newHits := referenceTxHits(queryNewChainBlocks())
928		oldSuffix := queryOldSuffixBlocks()
929		newBranch := queryNewShortBranch()
930	
931		const pageSize = 2
932		const reorgers = 2
933		const rounds = 40
934		const tipReaders = 4
935		const runs = 60
936		const pinnedReaders = 2
937	
938		stop := make(chan struct{})
939		var wg sync.WaitGroup
940		for r := 0; r < reorgers; r++ {
941			wg.Add(1)
942			go func(seed int) {
943				defer wg.Done()
944				for i := 0; i < rounds; i++ {
945					select {
946					case <-stop:
947						return
948					default:
949					}
950					branch := newBranch
951					if (i+seed)%2 == 0 {
952						branch = oldSuffix
953					}
954					if _, err := index.Reorg(branch); err != nil {
955						t.Errorf("reorg failed: %v", err)
956						return
957					}
958				}
959			}(r)
960		}
961	
962		for r := 0; r < tipReaders; r++ {
963			wg.Add(1)
964			go func() {
965				defer wg.Done()
966				for run := 0; run < runs; run++ {
967					select {
968					case <-stop:
969						return
970					default:
971					}
972					first, err := index.QueryTxs(TxQuery{PageSize: pageSize})
973					if err != nil {
974						t.Errorf("first page failed: %v", err)
975						return
976					}
977					var branchHits []TxHit
978					switch first.ToHeight {
979					case 5:
980						branchHits = oldHits
981					case 4:
982						branchHits = newHits
983					default:
984						t.Errorf("first page pinned unknown tip %d", first.ToHeight)
985						return
986					}
987					total, blocks, to := first.TotalMatches, first.MatchedBlocks, first.ToHeight
988					if total != int64(len(branchHits)) {
989						t.Errorf("first page total=%d for tip %d, hits on that branch=%d", total, to, len(branchHits))
990						return
991					}
992					if err := classifyTxPage(first,
993						referenceTxPage(queryOldChainBlocks(), pageSize, 0),
994						referenceTxPage(queryNewChainBlocks(), pageSize, 0),
995						oldHits, newHits); err != nil {
996						t.Errorf("%v", err)
997						return
998					}
999					seen := append([]TxHit{}, first.Hits...)
1000					if !reflect.DeepEqual(first.Hits, branchHits[:len(first.Hits)]) {
1001						t.Errorf("first page records do not match the pinned branch:\n%+v", first.Hits)
1002						return
1003					}
1004					query := TxQuery{PageSize: pageSize, Cursor: first.NextCursor}
1005					for query.Cursor != "" {
1006						page, err := index.QueryTxs(query)
1007						if errors.Is(err, ErrQueryChanged) {
1008							if !reflect.DeepEqual(page, TxPage{}) {
1009								t.Errorf("changed continuation leaked %+v", page)
1010							}
1011							break // the pinned branch was replaced; restart from a first page
1012						}
1013						if err != nil {
1014							t.Errorf("continuation failed: %v", err)
1015							return
1016						}
1017						if page.TotalMatches != total || page.MatchedBlocks != blocks || page.ToHeight != to {
1018							t.Errorf("statistics drifted mid-pagination: %+v", page)
1019							return
1020						}
1021						wantSlice := branchHits[len(seen):]
1022						if len(wantSlice) > pageSize {
1023							wantSlice = wantSlice[:pageSize]
1024						}
1025						if !reflect.DeepEqual(page.Hits, wantSlice) {
1026							t.Errorf("continuation records do not match the pinned branch:\n%+v", page.Hits)
1027							return
1028						}
1029						seen = append(seen, page.Hits...)
1030						query.Cursor = page.NextCursor
1031						if query.Cursor == "" && len(seen) != len(branchHits) {
1032							t.Errorf("cursor chain ended after %d hits, branch has %d", len(seen), len(branchHits))
1033							return
1034						}
1035					}
1036				}
1037			}()
1038		}
1039	
1040		// Readers pinned to [1,2] must never be affected: every reorg replaces
1041		// heights 3+ and both branches always cover height 2.
1042		for r := 0; r < pinnedReaders; r++ {
1043			wg.Add(1)
1044			go func() {
1045				defer wg.Done()
1046				for run := 0; run < runs; run++ {
1047					select {
1048					case <-stop:
1049						return
1050					default:
1051					}
1052					query := TxQuery{From: 1, To: 2, PageSize: pageSize}
1053					var all []TxHit
1054					for {
1055						page, err := index.QueryTxs(query)
1056						if err != nil {
1057							t.Errorf("pinned-range query must never fail across suffix-only reorgs: %v", err)
1058							return
1059						}
1060						if page.TotalMatches != 3 || page.MatchedBlocks != 2 || page.ToHeight != 2 {
1061							t.Errorf("pinned statistics drifted: %+v", page)
1062							return
1063						}
1064						all = append(all, page.Hits...)
1065						if page.NextCursor == "" {
1066							break
1067						}
1068						query.Cursor = page.NextCursor
1069					}
1070					want := []TxHit{
1071						{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
1072						{Height: 1, BlockHash: "h1", TxID: "x", Position: 1},
1073						{Height: 2, BlockHash: "h2", TxID: "y", Position: 0},
1074					}
1075					if !reflect.DeepEqual(all, want) {
1076						t.Errorf("pinned records lost, duplicated, or contaminated: %v", all)
1077						return
1078					}
1079				}
1080			}()
1081		}
1082	
1083		wg.Wait()
1084		close(stop)
1085	
1086		// Leave the index deterministically on the shortened new chain and verify
1087		// the complete answer against the oracle.
1088		if _, err := index.Reorg(newBranch); err != nil {
1089			t.Fatalf("final reorg failed: %v", err)
1090		}
1091		final, err := index.QueryTxs(TxQuery{PageSize: pageSize})
1092		if err != nil {
1093			t.Fatal(err)
1094		}
1095		if !reflect.DeepEqual(viewOf(final), viewOf(referenceTxPage(queryNewChainBlocks(), pageSize, 0))) {
1096			t.Fatalf("final first page is not the complete new-chain answer:\n%+v", final)
1097		}
1098		var all []TxHit
1099		query := TxQuery{PageSize: pageSize, Cursor: final.NextCursor}
1100		all = append(all, final.Hits...)
1101		for query.Cursor != "" {
1102			page, err := index.QueryTxs(query)
1103			if err != nil {
1104				t.Fatalf("final pagination failed: %v", err)
1105			}
1106			all = append(all, page.Hits...)
1107			query.Cursor = page.NextCursor
1108		}
1109		if !reflect.DeepEqual(all, newHits) {
1110			t.Fatalf("final chain pagination=%v, want %v", all, newHits)
1111		}
1112	}
